package kavungen

import (
	"fmt"
	"go/format"
	"maps"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"github.com/jokruger/kavun/core/member"
)

// GeneratedFile is the name of the one generated Go file per package.
const GeneratedFile = "kavun_gen.go"

// generatedHeader opens every generated file; a kavun_gen.go without it is not ours and is never overwritten.
const generatedHeader = "// Code generated by kavun-gen; DO NOT EDIT.\n"

const (
	importCore    = "github.com/jokruger/kavun/core"
	importMember  = "github.com/jokruger/kavun/core/member"
	importMembers = "github.com/jokruger/kavun/core/member/members"
	importValue   = "github.com/jokruger/kavun/core/value"
)

// emitGo renders a package's kavun_gen.go: the binding of its //kavun:names, the type tables, the builtins' init and
// the module's init, in that order. importPaths gives the import path of each package directory in m.foreign. The
// output is gofmt-formatted and depends on nothing but the model, so equal input gives equal bytes.
func emitGo(ctx *Context, m *packageModel, importPaths map[string]string) ([]byte, error) {
	// q qualifies a core identifier: bare inside package core, "core.X" anywhere else.
	q := "core."
	if m.pkgName == "core" {
		q = ""
	}

	imports := map[string]bool{}
	var body strings.Builder

	// ident answers the Go expression of a member name's id: members.X for a builtin name, the //kavun:names key
	// for an embedder's — bare in its own package, qualified by its package's name from another.
	ident := func(name string) string {
		if id := ctx.memberIdents[name]; id != "" {
			imports[importMembers] = true
			return "members." + id
		}
		def := m.run[name]
		if def.dir == m.dir {
			return def.Key
		}
		imports[importPaths[def.dir]] = true
		return def.pkgName + "." + def.Key
	}
	for dir := range m.foreign {
		path := importPaths[dir]
		if path == "" {
			return nil, fmt.Errorf("package %s: no import path for %s, whose //kavun:names it uses", m.pkgName, dir)
		}
	}
	if err := checkQualifiers(m); err != nil {
		return nil, err
	}

	if m.names != nil {
		imports[importMember] = true
		names := slices.Clone(m.names.Names)
		slices.SortFunc(names, func(a, b NameDecl) int { return strings.Compare(a.Name, b.Name) })
		fmt.Fprintf(&body, "\n// The member names declared by the //kavun:names directive on %s (%s), bound while the package's\n", m.names.GoVar, filepath.Base(m.names.Pos.Filename))
		body.WriteString("// variables are initialized: before any init function of the package runs, so a type or module it registers\n// finds them bound.\n")
		body.WriteString("var _ = func() bool {\n")
		for _, n := range names {
			fmt.Fprintf(&body, "\tmember.Define(%s, %s)\n", n.Key, strconv.Quote(n.Name))
		}
		body.WriteString("\treturn true\n}()\n")
	}

	for _, t := range m.types {
		if !t.hasMembers {
			continue // a members-less type (record, module): its page only, no table
		}
		if q != "" {
			imports[importCore] = true
		}
		varName := methodsVar(t.stem)
		fmt.Fprintf(&body, "\n// %s is the %s type's member table,\n// generated from the directives in %s.\n", varName, t.decl.Name, memberSources(t))
		fmt.Fprintf(&body, "var %s = []%sMethod{\n", varName, q)
		members := slices.Clone(t.members)
		slices.SortFunc(members, func(a, b Directive) int { return compareMembers(a.Name, b.Name) })
		for _, d := range members {
			ctor := "NewMethod"
			if d.Pure {
				ctor = "NewPureMethod"
			}
			id := ident(d.Name)
			line := fmt.Sprintf("\t%s: %s%s(%s, %s),\n", id, q, ctor, strconv.Quote(d.Template), d.GoFunc)
			if tooLong(line) {
				line = fmt.Sprintf("\t%s: %s%s(\n\t\t%s,\n\t\t%s,\n\t),\n", id, q, ctor, strconv.Quote(d.Template), d.GoFunc)
			}
			body.WriteString(line)
		}
		body.WriteString("}\n")
	}

	if m.builtins != nil {
		if q != "" {
			imports[importCore] = true
		}
		body.WriteString("\n// init registers the free builtin functions declared by the //kavun:builtin directives.\n")
		body.WriteString("func init() {\n")
		fmt.Fprintf(&body, "\tfns := map[uint64]*%sBuiltinFunction{\n", q)
		for _, d := range m.builtinFuncs {
			fmt.Fprintf(&body, "\t\t%d: %sNewBuiltinFunction(%s, %s, %s, %t),\n", d.Slot, q, strconv.Quote(d.Name), strconv.Quote(d.Template), d.GoFunc, d.Pure)
		}
		body.WriteString("\t}\n\n")
		fmt.Fprintf(&body, `	for i, fn := range fns {
		id := uint64(%[1]sGlobalSlotBase) + i
		%[1]sBuiltinFunctions[id] = fn
		BuiltinFunctions[fn.Name] = %[1]sBuiltinFunctionValue(id)
	}

	BuiltinFunctionNames = make([]string, 0, len(fns))
	for id := %[1]sGlobalSlotBase; id < %[1]sGlobalSlotBase+%[1]sModuleSlotSize; id++ {
		if fn := %[1]sBuiltinFunctions[id]; fn != nil {
			BuiltinFunctionNames = append(BuiltinFunctionNames, fn.Name)
		}
	}
}
`, q)
	}

	if m.module != nil {
		if q != "" {
			imports[importCore] = true
		}
		if strings.HasPrefix(m.module.ModuleID, "value.") {
			imports[importValue] = true
		}
		declaredBy := "//kavun:module and //kavun:fn directives"
		if len(m.moduleConsts) > 0 {
			declaredBy = "//kavun:module, //kavun:fn and //kavun:const directives"
		}
		fmt.Fprintf(&body, "\n// init registers the %s module declared by the %s.\n", m.module.Name, declaredBy)
		body.WriteString("func init() {\n")
		fmt.Fprintf(&body, "\tm := %sNewModule(%s, %s, %t)\n", q, m.module.ModuleID, strconv.Quote(m.module.Name), m.module.Pure)
		for _, d := range m.moduleFuncs {
			method := "Fn"
			if d.Pure {
				method = "PureFn"
			}
			id := ident(d.Name)
			line := fmt.Sprintf("\tm.%s(%s, %d, %s, %s)\n", method, id, d.Slot, strconv.Quote(d.Template), d.GoFunc)
			if tooLong(line) {
				line = fmt.Sprintf("\tm.%s(\n\t\t%s, %d,\n\t\t%s,\n\t\t%s,\n\t)\n", method, id, d.Slot, strconv.Quote(d.Template), d.GoFunc)
			}
			body.WriteString(line)
		}
		for _, d := range m.moduleConsts {
			fmt.Fprintf(&body, "\tm.Const(%s, %s)\n", ident(d.Name), d.GoVar)
		}
		if m.hasExtras {
			fmt.Fprintf(&body, "\t%s(m)\n", extrasFunc)
		}
		body.WriteString("\tif err := m.Register(); err != nil {\n\t\tpanic(err)\n\t}\n}\n")
	}

	var src strings.Builder
	src.WriteString(generatedHeader)
	fmt.Fprintf(&src, "\npackage %s\n", m.pkgName)
	paths := make([]string, 0, len(imports))
	for p := range imports {
		paths = append(paths, p)
	}
	slices.Sort(paths)
	switch len(paths) {
	case 0:
	case 1:
		fmt.Fprintf(&src, "\nimport %s\n", strconv.Quote(paths[0]))
	default:
		src.WriteString("\nimport (\n")
		for _, p := range paths {
			fmt.Fprintf(&src, "\t%s\n", strconv.Quote(p))
		}
		src.WriteString(")\n")
	}
	src.WriteString(body.String())

	out, err := format.Source([]byte(src.String()))
	if err != nil {
		return nil, fmt.Errorf("formatting the generated %s for package %s: %v", GeneratedFile, m.pkgName, err)
	}
	return out, nil
}

// compareMembers orders a table's entries: the builtin names by id, then the embedder's names (//kavun:names) by
// name — their ids are bound by the embedder's code, which the generator does not run.
func compareMembers(a, b string) int {
	ia, ib := member.Lookup(a), member.Lookup(b)
	switch {
	case ia != member.Unknown && ib != member.Unknown:
		return int(ia) - int(ib)
	case ia != member.Unknown:
		return -1
	case ib != member.Unknown:
		return 1
	}
	return strings.Compare(a, b)
}

// checkQualifiers refuses a package whose tables would name two packages by one qualifier: two packages of the run
// with the same name, or one named like an import of the generated file or the package itself.
func checkQualifiers(m *packageModel) error {
	taken := map[string]string{"core": importCore, "member": importMember, "members": importMembers, "value": importValue, m.pkgName: m.dir}
	for _, dir := range slices.Sorted(maps.Keys(m.foreign)) {
		var pkgName string
		for _, def := range m.run {
			if def.dir == dir {
				pkgName = def.pkgName
				break
			}
		}
		if prev, ok := taken[pkgName]; ok {
			return fmt.Errorf("package %s: uses the //kavun:names of package %s (%s), whose name is already taken by %s in the generated file: rename one", m.pkgName, pkgName, dir, prev)
		}
		taken[pkgName] = dir
	}
	return nil
}

// methodsVar names a type's generated table after its root file: "array" → "arrayMethods",
// "int_range" → "intRangeMethods".
func methodsVar(stem string) string {
	parts := strings.Split(stem, "_")
	for i := 1; i < len(parts); i++ {
		if parts[i] != "" {
			parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:]
		}
	}
	return strings.Join(parts, "") + "Methods"
}

// memberSources names the files a type's member directives sit in, in name order: "array_members.go", or the root
// "file.go" of a module-owned type, or both.
func memberSources(t *typeModel) string {
	seen := map[string]bool{}
	var names []string
	for _, d := range t.members {
		if n := filepath.Base(d.Pos.Filename); !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	slices.Sort(names)
	return strings.Join(names, " and ")
}

// maxLine is the longest generated line, a tab counted as four columns; an entry past it is written over several lines
// (a long template), which gofmt keeps.
const maxLine = 120

// tooLong reports whether a generated line, gofmt's key alignment aside, would pass maxLine.
func tooLong(line string) bool {
	return len(strings.ReplaceAll(strings.TrimSuffix(line, "\n"), "\t", "    "))+20 > maxLine
}
